export function createSound({enabled=()=>true,volume=()=>.35,AudioContext=globalThis.AudioContext||globalThis.webkitAudioContext}={}){
 let context=null,lastTick=-Infinity,voices=new Set();
 async function unlock(){if(!enabled()||!AudioContext)return false;try{context??=new AudioContext();if(context.state==='suspended')await context.resume();return context.state==='running'}catch{return false}}
 function tone(frequency,start,length,level,type='sine'){if(!enabled()||volume()<=0||!context||context.state!=='running')return;try{const oscillator=context.createOscillator(),gain=context.createGain(),at=context.currentTime+start;oscillator.type=type;oscillator.frequency.setValueAtTime(frequency,at);oscillator.frequency.exponentialRampToValueAtTime(frequency*.985,at+length);const peak=level*volume();gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,peak),at+.008);gain.gain.exponentialRampToValueAtTime(.0001,at+length);oscillator.connect(gain);gain.connect(context.destination);voices.add(oscillator);oscillator.onended=()=>{voices.delete(oscillator);oscillator.disconnect();gain.disconnect()};oscillator.start(at);oscillator.stop(at+length+.01)}catch{}}
 return {unlock,tick(index=0){if(!context||context.currentTime-lastTick<.055)return;lastTick=context.currentTime;tone(480+(index%5)*36,0,.047,.16,'triangle')},success(){tone(784,0,.72,.23);tone(1176,0,.42,.055);tone(1046.5,.62,.75,.17);tone(1568,.62,.45,.035)},stop(){for(const voice of voices){try{voice.stop()}catch{}}voices.clear()},get unlocked(){return context?.state==='running'}};
}
